#!/usr/bin/env python3
"""
Builds StealAnItem.rbxlx — the complete, ready-to-open Roblox place.

    python3 tools/build_place.py            # writes StealAnItem.rbxlx + sourcemap.json

What goes into the place:
  * Workspace.Map            generated by tools/map_builder.py (town, houses, warehouses + treadmills, shop)
  * ReplicatedStorage.Shared src/shared/*.luau  (ModuleScripts)
  * ReplicatedStorage.Remotes RemoteEvents/RemoteFunctions used by the game
  * ServerScriptService.Server   src/server (Script + child ModuleScripts)
  * StarterPlayerScripts.Client  src/client (LocalScript + child ModuleScripts)
  * Lighting settings

Script folders follow Rojo's conventions (init.server.luau, init.client.luau,
*.luau = ModuleScript), so default.project.json can also live-sync them.

Only the Python standard library is required.
"""

from __future__ import annotations

import argparse
import json
import os
import sys
import time

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

import map_builder  # noqa: E402
from rbxlx import C3, Float, Inst, Protected, Token, serialize  # noqa: E402

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

REMOTE_EVENTS = ["Notify", "Busted"]
REMOTE_FUNCTIONS = ["Purchase", "SpawnCar", "Treadmill"]


def script_class_for(filename: str) -> tuple[str, str] | None:
    """Maps a file name to (instance name, class name) using Rojo's rules."""
    for suffix, class_name in ((".server.luau", "Script"), (".client.luau", "LocalScript"), (".luau", "ModuleScript")):
        if filename.endswith(suffix):
            return filename[: -len(suffix)], class_name
    return None


def load_script_dir(path: str, name: str) -> Inst:
    """Loads a directory the way Rojo does: an init file turns the folder into that script."""
    entries = sorted(os.listdir(path))
    init_file = None
    init_class = "Folder"
    for candidate, class_name in (("init.server.luau", "Script"), ("init.client.luau", "LocalScript"), ("init.luau", "ModuleScript")):
        if candidate in entries:
            init_file, init_class = candidate, class_name
            break

    inst = Inst(init_class, name)
    if init_file:
        rel = os.path.relpath(os.path.join(path, init_file), ROOT)
        with open(os.path.join(path, init_file), encoding="utf-8") as handle:
            inst.set(Source=Protected(handle.read()))
        inst.source_path = rel

    for entry in entries:
        full = os.path.join(path, entry)
        if entry == init_file:
            continue
        if os.path.isdir(full):
            inst.add(load_script_dir(full, entry))
            continue
        mapped = script_class_for(entry)
        if not mapped:
            continue
        child_name, class_name = mapped
        child = Inst(class_name, child_name, inst)
        with open(full, encoding="utf-8") as handle:
            child.set(Source=Protected(handle.read()))
        child.source_path = os.path.relpath(full, ROOT)
    return inst


def build_lighting() -> Inst:
    lighting = Inst("Lighting", "Lighting")
    lighting.set(
        ClockTime=Float(14.2),
        Brightness=Float(2.6),
        Ambient=C3.rgb(92, 92, 104),
        OutdoorAmbient=C3.rgb(138, 138, 150),
        GlobalShadows=True,
        Technology=Token(3),  # ShadowMap
        EnvironmentDiffuseScale=Float(1),
        EnvironmentSpecularScale=Float(1),
        ShadowSoftness=Float(0.25),
    )
    atmosphere = Inst("Atmosphere", "Atmosphere", lighting)
    atmosphere.set(
        Density=Float(0.28),
        Offset=Float(0.2),
        Color=C3.rgb(205, 220, 235),
        Decay=C3.rgb(120, 140, 170),
        Glare=Float(0.2),
        Haze=Float(1.2),
    )
    bloom = Inst("BloomEffect", "Bloom", lighting)
    bloom.set(Intensity=Float(0.6), Size=Float(24), Threshold=Float(1.6))
    color = Inst("ColorCorrectionEffect", "ColorCorrection", lighting)
    color.set(Saturation=Float(0.12), Contrast=Float(0.05), Brightness=Float(0.01))
    return lighting


def build_datamodel() -> list[Inst]:
    workspace = Inst("Workspace", "Workspace")
    workspace.set(StreamingEnabled=False)
    map_builder.build_map(workspace)
    Inst("Folder", "Cars", workspace)

    replicated = Inst("ReplicatedStorage", "ReplicatedStorage")
    replicated.add(load_script_dir(os.path.join(ROOT, "src", "shared"), "Shared"))
    remotes = Inst("Folder", "Remotes", replicated)
    for name in REMOTE_EVENTS:
        Inst("RemoteEvent", name, remotes)
    for name in REMOTE_FUNCTIONS:
        Inst("RemoteFunction", name, remotes)

    server_scripts = Inst("ServerScriptService", "ServerScriptService")
    server_scripts.add(load_script_dir(os.path.join(ROOT, "src", "server"), "Server"))

    starter_player = Inst("StarterPlayer", "StarterPlayer")
    player_scripts = Inst("StarterPlayerScripts", "StarterPlayerScripts", starter_player)
    player_scripts.add(load_script_dir(os.path.join(ROOT, "src", "client"), "Client"))

    return [workspace, build_lighting(), replicated, server_scripts, starter_player]


def sourcemap_node(inst: Inst, include_map: bool) -> dict | None:
    """Rojo-style sourcemap node (used by luau-lsp for type checking)."""
    if inst.class_name == "Workspace" and not include_map:
        children = [c for c in inst.children if c.name != "Map"]
    else:
        children = inst.children
    node: dict = {"name": inst.name, "className": inst.class_name}
    if inst.source_path:
        node["filePaths"] = [inst.source_path.replace(os.sep, "/")]
    kids = []
    for child in children:
        # Only scripts, folders/services that contain scripts, and remotes matter for typing.
        if child.class_name in ("Part", "WedgePart", "SpawnLocation", "Model") and not include_map:
            continue
        sub = sourcemap_node(child, include_map)
        if sub:
            kids.append(sub)
    if kids:
        node["children"] = kids
    return node


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--output", default=os.path.join(ROOT, "StealAnItem.rbxlx"))
    parser.add_argument("--sourcemap", default=os.path.join(ROOT, "sourcemap.json"))
    args = parser.parse_args()

    started = time.time()
    roots = build_datamodel()
    xml = serialize(roots)
    with open(args.output, "w", encoding="utf-8", newline="\n") as handle:
        handle.write(xml)

    datamodel = {
        "name": "StealAnItem",
        "className": "DataModel",
        "filePaths": ["default.project.json"],
        "children": [n for n in (sourcemap_node(r, False) for r in roots) if n],
    }
    with open(args.sourcemap, "w", encoding="utf-8", newline="\n") as handle:
        json.dump(datamodel, handle, indent=1)
        handle.write("\n")

    count = sum(1 + sum(1 for _ in r.descendants()) for r in roots)
    parts = sum(1 for r in roots for d in r.descendants() if d.class_name in ("Part", "WedgePart", "SpawnLocation", "CornerWedgePart"))
    size_mb = os.path.getsize(args.output) / (1024 * 1024)
    print(f"Wrote {os.path.relpath(args.output, ROOT)}: {count} instances ({parts} parts), {size_mb:.2f} MB in {time.time() - started:.1f}s")
    print(f"Wrote {os.path.relpath(args.sourcemap, ROOT)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
